               {"name": "Trial A", "values": [10, 25, 30]},
               {"name": "Trial B", "values": [15, 28, 25]},
               {"name": "Trial C", "values": [20, 22, 23]}
             ]
           }
         },
         {
           "title": "Comparison of Trials",
           "layout": "table",
           "takeaway": "Detailed comparison between trial results.",
           "table": {
             "headers": ["Trial", "Yield", "Success Rate"],
