               ["Trial B", "32", "60%"],
               ["Trial C", "25", "80%]
             ]
           }
         },
         {
           "title": "Yield Chart",
           "layout": "chart",
           "takeaway": "Visual representation of yield trends.",
           "callout": "High variability observed in Trial A and B."
         }
       ]
     }
   }
   ```

